import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.RequestBody;

public class ApplyReassign {
    // Only a role the permission matrix allows to reassign (by default a steward) moves a claim, and only a DRAFT, OPEN or PENDING one, to a person on the sheet who was not
    // retired by its date (its own person too: it then lists first under them again, as when a bulk move takes it there). A correction stays with the person whose settled claim it corrects. Stored only if the
    // claim still has the person and status it was loaded with.
    public void apply(@RequestBody(required = false) ReassignRequest body, @Val Claim claim, Claims claims,
            People people, Settings settings, Sheets sheets, Periods periods, ServerHttpConnection connection, Out<ClaimResponse> responseOut,
            Out<Person> toOut) throws ClaimReassignRefusedException, ClaimAfterRetirementException {
        String user = Audit.user(connection).trim();
        if (!settings.permits(claim.sheetId(), "reassign", user)) {
            throw new ClaimReassignRefusedException("Your role is not allowed to move a claim to another person.");
        }
        if (!(claim.status() == ClaimStatus.DRAFT || claim.status().isOpen())) {
            throw new ClaimReassignRefusedException("A " + claim.status() + " claim cannot move to another person.");
        }
        if (claim.isCorrection()) {
            throw new ClaimReassignRefusedException("A correction stays with the person whose claim it corrects.");
        }
        Person to = body == null || body.personId() == null ? null : people.find(claim.sheetId(), body.personId());
        if (to == null) {
            throw new ClaimReassignRefusedException("Choose a person on this sheet to move the claim to.");
        }
        RefuseRetiredInput.check(to, claim.date());
        // A numbered claim takes the next number of the sequence it would be opened in (as ApplyClaimStatus).
        String scope = null;
        LocalDate numberingFrom = settings.periodNumberingFrom(claim.sheetId());
        if (numberingFrom != null && !sheets.today(claim.sheetId()).isBefore(numberingFrom)) {
            Period period = periods.on(claim.sheetId(), claim.dueBy());
            scope = period == null ? "" : period.name();
        }
        Claim moved = claims.reassign(claim, to.id(), scope);
        if (moved == null) {
            throw new ClaimReassignRefusedException("The claim has changed since it was loaded.");
        }
        responseOut.set(ClaimResponse.from(moved));
        toOut.set(to);
    }
}
        // of n/a is within any threshold).
        if (next == ClaimStatus.OPEN && claim.status() == ClaimStatus.DRAFT && due != null
                && (claim.note() == null || claim.note().isBlank())) {
            BigDecimal threshold = settings.noteThreshold(claim.sheetId(), claim.date());
            if (threshold != null && due.compareTo(threshold) > 0) {
                throw new ClaimNoteNeededException("The claim's due is above the note threshold (" + threshold.toPlainString()
                        + "): give it a note before it is opened.");
            }
        }
        // A clerk settles only a claim whose due is at or below the clerk limit (a due of n/a is within any
        // limit); above it the claim goes PENDING, for a steward to approve. A steward settles anything.
        if (next == ClaimStatus.SETTLED && claim.status() == ClaimStatus.OPEN && due != null && !steward) {
            BigDecimal limit = settings.clerkLimit(claim.sheetId());
            if (limit != null && due.compareTo(limit) > 0) {
                next = ClaimStatus.PENDING;
            }
        }
        // While the sheet numbers by period (its today on or after the from-date), an opened claim is numbered
        // within the period its due-by falls in, or in the no-period sequence; otherwise sheet-wide.
        String scope = null;
        LocalDate numberingFrom = settings.periodNumberingFrom(claim.sheetId());
        if (next == ClaimStatus.OPEN && numberingFrom != null && !sheets.today(claim.sheetId()).isBefore(numberingFrom)) {
            Period period = periods.on(claim.sheetId(), claim.dueBy());
            scope = period == null ? "" : period.name();
        }
        Claim changed = claims.changeStatus(claim, next, due, user, scope);
        if (changed == null) {
            throw new ClaimStatusRefusedException("A " + claim.status() + " claim cannot become " + next + ".");
        }
        // Settled one at a time, the claim leaves any batch that settled it before (a bulk settle records its batch after).
        if (!decision && (next == ClaimStatus.SETTLED || next == ClaimStatus.PENDING)) {
            batches.remove(changed.id());
        }
        if (next == ClaimStatus.VOID && !voidReason.isEmpty()) {
            voidReasons.voided(changed.id(), voidReason);
        }
        claims.log(changed, user, sheets.today(claim.sheetId()), rollup.figure(changed));
        responseOut.set(ClaimResponse.from(changed));
        requestOut.set(new ClaimStatusRequest(action, reason, voidReason));
    }

    /**
     * The claim's due now, before its late charge: the figure its person's last statement bound it to (a PENDING
     * claim is not bound: its figure is live), otherwise its amount times its
     * person's grade's rate on the claim's date, rounded by the policy date (not yet floored); null when none applies.
     */
    private static BigDecimal due(Claim claim, People people, Rates rates, Settings settings) {
        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
            return claim.statedDue();
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        if (person == null) {
            return null;
        }
        BigDecimal rate = rates.on(claim.sheetId(), person.gradeOn(claim.date()), claim.date());
        return settings.live(claim, rate);
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.history.AsOf;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The store of sheets. A sheet never stored is an empty sheet whose today is the real date. */
@Repository
public class Sheets {

    private final JdbcTemplate jdbc;

    public Sheets(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Sheet find(String id) {
        // While the store is read as of a date, that date stands in for the sheet's today.
        LocalDate asOf = AsOf.date();
        List<Sheet> found = jdbc.query("SELECT today_date, archived FROM " + AsOf.table("sheet") + " WHERE id = ?",
                (rs, n) -> new Sheet(id, asOf != null ? asOf : rs.getObject(1, LocalDate.class), rs.getBoolean(2)), id);
        return found.isEmpty() ? new Sheet(id, asOf != null ? asOf : LocalDate.now(), false) : found.get(0);
    }

    /** The sheet's today: use this, never the real clock, for anything that depends on the date. */
    public LocalDate today(String id) {
        return find(id).today();
    }

    /** Whether the sheet is archived, and so refuses every change. */
    public boolean isArchived(String id) {
        return find(id).archived();
    }

    /** Keeps the id as a sheet that has been loaded. */
    public void markLoaded(String id) {
        jdbc.update("MERGE INTO sheet_loaded (id) KEY (id) VALUES (?)", id);
    }

    /** Whether the sheet has been loaded (or changed) before. */
    public boolean exists(String id) {
        Integer n = jdbc.queryForObject("SELECT (SELECT COUNT(*) FROM sheet_loaded WHERE id = ?) + (SELECT COUNT(*) FROM sheet WHERE id = ?)",
                Integer.class, id, id);
        return n != null && n > 0;
    }

    public void save(Sheet sheet) {
        jdbc.update("MERGE INTO sheet (id, today_date, archived) KEY (id) VALUES (?, ?, ?)", sheet.id(), sheet.today(),
                sheet.archived());
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class RefuseNonSteward {
    // Only a steward (a delegation included) archives a sheet.
    public void refuse(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection, Settings settings)
            throws SheetArchiveRefusedException {
        if (!Settings.STEWARD.equals(settings.role(sheetId.trim(), Audit.user(connection).trim()))) {
            throw new SheetArchiveRefusedException("Only a steward can archive the sheet.");
        }
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Val;

public class MarkSheetLoaded {
    public void mark(@Val Sheet sheet, Sheets sheets) {
        sheets.markLoaded(sheet.id());
    }
}
package net.officefloor.hq.app.sheet;

import org.springframework.web.bind.annotation.PathVariable;

public class RefuseArchived {
    // An archived sheet keeps everything visible and changes nothing: every write is refused before anything is read, stored or recorded.
    public void refuse(@PathVariable("sheetId") String sheetId, Sheets sheets) throws SheetArchivedException {
        if (sheets.isArchived(sheetId.trim())) {
            throw new SheetArchivedException("The sheet is archived: it can change nothing.");
        }
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class RefuseViewer {
    // A viewer sees every screen and figure but changes nothing: every write is refused before anything is read, stored or recorded.
    public void refuse(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection, Settings settings)
            throws ViewerRefusedException {
        if (settings.isViewer(sheetId.trim(), Audit.user(connection))) {
            throw new ViewerRefusedException("A viewer can change nothing.");
        }
    }
}

